 internal static object Metadata(string path){try{using(var f=File.OpenRead(path)){var h=Read(f,0,12);string tag=Tag(h,0);if(tag!="OTTO"&&U32(h,0)!=0x10000&&tag!="true")return Unknown();int n=U16(h,4);if(n>256)return Unknown();var dir=Read(f,12,n*16);for(int i=0;i<n;i++){int p=i*16;if(Tag(dir,p)!="fvar")continue;uint offset=U32(dir,p+8),length=U32(dir,p+12);if(length<16||length>262144)return Unknown();var b=Read(f,offset,(int)length);int count=U16(b,8),stride=U16(b,10),start=U16(b,4);if(count>32||stride<20||start+count*stride>b.Length)return Unknown();var axes=new List<object>();for(int j=0;j<count;j++){int o=start+j*stride;double min=(int)U32(b,o+4)/65536.0,def=(int)U32(b,o+8)/65536.0,max=(int)U32(b,o+12)/65536.0;if(min>def||def>max)continue;axes.Add(new{tag=Tag(b,o),min=min,@default=def,max=max});}return new{variable=(bool?)(axes.Count>0),axes=axes,format=tag=="OTTO"?"OpenType":"TrueType"};}return new{variable=(bool?)false,axes=new object[0],format=tag=="OTTO"?"OpenType":"TrueType"};}}catch{return Unknown();}}
