 internal static string Category(string path,string family){try{if(path!=null)using(var f=File.OpenRead(path)){var h=Read(f,0,12);int n=U16(h,4);if(n<=256){var dir=Read(f,12,n*16);for(int i=0;i<n;i++){int p=i*16;uint offset=U32(dir,p+8),length=U32(dir,p+12);if(Tag(dir,p)=="post"&&length>=16&&U32(Read(f,offset+12,4),0)!=0)return "Mono";if(Tag(dir,p)=="OS/2"&&length>=42){var b=Read(f,offset+32,10);if(b[0]==2){if(b[3]==9)return "Mono";if(b[1]>=2&&b[1]<=10)return "Serif";if(b[1]>=11&&b[1]<=15)return "Sans";}if(b[0]==3||b[0]==4)return "Display";}}}}}catch{}string name=(family??"").ToLowerInvariant();if(System.Text.RegularExpressions.Regex.IsMatch(name,"mono|courier|consolas|typewriter|code"))return "Mono";if(System.Text.RegularExpressions.Regex.IsMatch(name,"serif|times|georgia|garamond|cambria|baskerville|palatino|bodoni"))return "Serif";if(System.Text.RegularExpressions.Regex.IsMatch(name,"sans|arial|helvetica|verdana|segoe|calibri|tahoma|aptos|trebuchet|bahnschrift"))return "Sans";return "Uncategorised";}
 internal static List<object> Installed(){var files=new List<Tuple<string,string,string>>();foreach(var scope in new[]{"machine","user"})using(var key=(scope=="machine"?Registry.LocalMachine:Registry.CurrentUser).OpenSubKey(@"SOFTWARE\Microsoft\Windows NT\CurrentVersion\Fonts")){if(key==null)continue;foreach(var name in key.GetValueNames()){var file=Convert.ToString(key.GetValue(name));if(String.IsNullOrEmpty(file))continue;if(!Path.IsPathRooted(file))file=Path.Combine(scope=="machine"?Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),"Fonts"):Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),@"Microsoft\Windows\Fonts"),file);files.Add(Tuple.Create(name,file,scope));}}
 var list=new List<object>();using(var fonts=new InstalledFontCollection()){foreach(var family in fonts.Families){var candidates=files.FindAll(x=>x.Item1.StartsWith(family.Name+" (",StringComparison.OrdinalIgnoreCase)||x.Item1.StartsWith(family.Name+" Regular (",StringComparison.OrdinalIgnoreCase));if(candidates.Count==0)candidates=files.FindAll(x=>x.Item1.StartsWith(family.Name+" ",StringComparison.OrdinalIgnoreCase));candidates.Sort((a,b)=>a.Item1.Length.CompareTo(b.Item1.Length));var candidate=candidates.Count>0?candidates[0]:null;var styles=new List<string>();foreach(var style in new[]{FontStyle.Regular,FontStyle.Bold,FontStyle.Italic,FontStyle.Bold|FontStyle.Italic})if(family.IsStyleAvailable(style))styles.Add(style.ToString());list.Add(new{name=family.Name,family=family.Name,category=Category(candidate==null?null:candidate.Item2,family.Name),scope=candidate==null?"unknown":candidate.Item3,styles=styles,fontMeta=candidate==null?Unknown():Metadata(candidate.Item2)});}}return list;}
}
static class ShellPreview {
 [StructLayout(LayoutKind.Sequential)]struct Size{public int width,height;public Size(int w,int h){width=w;height=h;}}
 [ComImport,Guid("bcc18b79-ba16-442f-80c4-8a59c30c463b"),InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]interface ImageFactory{[PreserveSig]int GetImage(Size size,uint flags,out IntPtr bitmap);}
