 internal static Task<bool> TrySave(string source,string dest){var done=new TaskCompletionSource<bool>();var thread=new Thread(()=>{ImageFactory factory=null;IntPtr bitmap=IntPtr.Zero;try{var guid=typeof(ImageFactory).GUID;SHCreateItemFromParsingName(source,IntPtr.Zero,ref guid,out factory);if(factory.GetImage(new Size(640,640),8,out bitmap)!=0||bitmap==IntPtr.Zero){done.SetResult(false);return;}using(var image=Image.FromHbitmap(bitmap))image.Save(dest,System.Drawing.Imaging.ImageFormat.Png);done.SetResult(true);}catch{done.TrySetResult(false);}finally{if(bitmap!=IntPtr.Zero)DeleteObject(bitmap);if(factory!=null)Marshal.ReleaseComObject(factory);}});thread.IsBackground=true;thread.SetApartmentState(ApartmentState.STA);thread.Start();return done.Task;}
}
static class DocumentPreview {
 static uint U32(byte[]b,int p){return((uint)b[p]<<24)|((uint)b[p+1]<<16)|((uint)b[p+2]<<8)|b[p+3];}static string Tag(byte[]b,int p){return System.Text.Encoding.ASCII.GetString(b,p,4);}static byte[] Slice(byte[]b,int start,int size){var result=new byte[size];Buffer.BlockCopy(b,start,result,0,size);return result;}
 static byte[] Png(byte[]b){byte[] signature={137,80,78,71,13,10,26,10};for(int start=0;start+32<b.Length;start++){bool match=true;for(int i=0;i<8;i++)if(b[start+i]!=signature[i]){match=false;break;}if(!match||Tag(b,start+12)!="IHDR")continue;uint width=U32(b,start+16),height=U32(b,start+20);if(width==0||height==0||width>2048||height>2048)continue;int p=start+8,blocks=0;while(p+12<=b.Length&&blocks++<2048){uint length=U32(b,p);if(length>8000000||p+(long)length+12>b.Length)break;string type=Tag(b,p+4);p+=(int)length+12;if(type=="IEND")return Slice(b,start,p-start);}}return null;}
 internal static string TrySave(string source,string dest){try{var ext=Path.GetExtension(source).ToLowerInvariant();byte[] b;using(var f=File.OpenRead(source)){int length=(int)Math.Min(f.Length,8*1024*1024);if(new[]{".afdesign",".afphoto",".afpub",".af",".affinity",".aftemplate"}.Contains(ext)){b=new byte[length];f.Position=f.Length-length;f.Read(b,0,length);var png=Png(b);if(png==null){f.Position=0;f.Read(b,0,length);png=Png(b);}if(png!=null){using(var stream=new MemoryStream(png))using(var image=Image.FromStream(stream))image.Save(dest,System.Drawing.Imaging.ImageFormat.Png);return "Embedded Affinity image preview";}}else if(ext==".psd"||ext==".psb"){b=new byte[length];f.Read(b,0,length);if(length<34||Tag(b,0)!="8BPS")return null;long p=26;p+=4+U32(b,(int)p);if(p+4>b.Length)return null;long limit=p+4+U32(b,(int)p);p+=4;limit=Math.Min(limit,b.Length);while(p+12<=limit){if(Tag(b,(int)p)!="8BIM")break;int rid=(b[p+4]<<8)|b[p+5],name=1+b[p+6];p+=6+name+name%2;if(p+4>limit)break;uint size=U32(b,(int)p);p+=4;if(p+size>limit)break;if(rid==1036&&size>28&&U32(b,(int)p)==1){var jpeg=Slice(b,(int)p+28,(int)size-28);using(var stream=new MemoryStream(jpeg))using(var image=Image.FromStream(stream)){if(image.Width>2048||image.Height>2048)return null;image.Save(dest,System.Drawing.Imaging.ImageFormat.Png);}return "Photoshop embedded thumbnail";}p+=size+size%2;}}}return null;}catch{return null;}}
}
